def tidy(s): return re.sub(r"\s+", " ", s).strip()

def main():
    here = os.path.dirname(os.path.abspath(__file__))
    out = os.path.join(here, "..", "web", "src", "lang")
    for col, code in ((1, "de"), (2, "fr"), (3, "it")):
        entries = {}
        for row in ROWS:
            assert len(row) == 4, row
            key = tidy(row[0])
            for part in re.findall(r"\{[a-z]+\}", key):
                assert part in row[col], (code, key, part)
            entries[key] = row[col]
        body = ",\n".join(f"  {json.dumps(k, ensure_ascii=False)}: {json.dumps(v, ensure_ascii=False)}" for k, v in entries.items())
        with open(os.path.join(out, f"{code}.ts"), "w") as f:
            f.write(f"// Written by scripts/translations.py; change the table there.\nconst list: Record<string, string> = {{\n{body},\n}};\nexport default list;\n")
    print(len(ROWS), "texts in 3 languages")

if __name__ == "__main__":
    main()
